import{z as n,x as s,o as t,c as d,q as r,j as i,D as A,d as a,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"中断实践","description":"","frontmatter":{"title":"中断实践","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-interrupt-practice.md","filePath":"cs/emb-interrupt-practice.md","lastUpdated":1791063341000}'),p={name:"cs/emb-interrupt-practice.md"};function c(D,E,C,m,u,F){const B=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="中断实践" tabindex="-1">中断实践 <a class="header-anchor" href="#中断实践" aria-label="Permalink to &quot;中断实践&quot;">​</a></h1><div class="epigraph"><p>中断是硬件对软件说的一句「现在有事」；真正的工程量不在听到这句话，而在回答什么时候处理、处理多久、以及处理期间谁被挡在门外。</p><footer>—— 据 Yiu, The Definitive Guide to ARM Cortex-M3；RISC-V Privileged Spec 整理</footer></div><p><a href="/cs/emb-bare-metal-boot">上一课</a>把复位到 main 之间的启动契约补齐了，向量表里除复位项外的每一项都还指向空处理函数。本课把它们填上：外设的事件如何沿着「外设请求线—中断控制器—向量表入口—服务函数」这条链到达你的代码，以及写服务函数时哪些动作会毁掉整块板子的实时性。主干课的<a href="/cs/exception-interrupt-entry">异常与中断入口</a>讲过硬件如何保存 PC、跳到 <code>mtvec</code> 再用 <code>mret</code> 返回；本课不再推导入口协议，只写入口之后你必须做对的事。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>轮询是新手的第一反应：主循环里反复读外设状态寄存器。它的事件延迟取决于循环周期，CPU 在无事可做时也满负荷空转——对一个要用电池跑一年的设备，这不是低效，是不可行。缺口因此是<strong>把「何时有事」的决定权交给硬件</strong>：外设置位请求线，控制器按优先级仲裁，处理器在指令边界保存上下文并跳转。但把轮询换成中断只是换掉了一半问题，另一半是<a href="/cs/interrupt-bottom-half">中断下半部</a>讲过的老原理在无 OS 场景下的重演：上半部必须短，因为你在中断里占用的每一微秒，都在推迟同级与更低优先级事件的响应。</p><h3 id="服务函数的四条纪律" tabindex="-1">服务函数的四条纪律 <a class="header-anchor" href="#服务函数的四条纪律" aria-label="Permalink to &quot;服务函数的四条纪律&quot;">​</a></h3><p>第一，先清请求源再谈别的：不清就是退出后立即重入，栈被吃穿才发现「程序卡死」。第二，共享变量必须 <code>volatile</code> 并按位宽原子访问——编译器看不到中断会改它，会把「等待标志」的循环优化成死循环。第三，不许阻塞、不许 printf、不许忙等：服务函数里调用任何可能再次被中断打断还不重入的库，都是在攒一个概率性死机。第四，能推迟的都推迟：服务函数只置标志或投递队列，真正的工作留给主循环或 RTOS 任务。</p><p><span class="marginnote"><code>volatile</code> 是告诉编译器「这个变量会被你看不见的代码改」的关键字，中断服务函数正是编译器看不见的代码。不加它，编译器看到主循环里没人改等待标志，就把「原地等标志」优化成只读一次的死循环——这是中断编程最经典的初学者事故。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置一个中断的完整清单按链路顺序检查：外设侧使能事件并允许发请求；控制器侧设置优先级与使能位（NVIC 用几比特优先级加抢占分组，PLIC 走 <a href="/cs/plic-irq">PLIC 与中断号</a>的 claim/complete 流程）；向量表侧确认入口函数名与启动文件一致——名字打错一个字母，链接器不报错，事件照常发生，只是落进了默认死循环。临界区用关中断保护「读—改—写」共享状态，但窗口要按指令数而不是行数计算：关中断一百条指令，百兆主频下就是一微秒级的延迟抖动，直接吃掉后课要谈的实时余量。</p>',10)),(t(),i(l,null,{default:A(()=>[o(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E5%A4%96%E8%AE%BE%E4%BA%8B%E4%BB%B6%E7%BD%AE%E8%AF%B7%E6%B1%82%E4%BD%8D%22%5D%20--%3E%20CTRL%5B%22%E4%B8%AD%E6%96%AD%E6%8E%A7%E5%88%B6%E5%99%A8%E6%8C%89%E4%BC%98%E5%85%88%E7%BA%A7%E4%BB%B2%E8%A3%81%22%5D%0A%20%20CTRL%20--%3E%20ENTRY%5B%22%E7%A1%AC%E4%BB%B6%E4%BF%9D%E5%AD%98%E4%B8%8A%E4%B8%8B%E6%96%87%EF%BC%8C%E8%B7%B3%E5%90%91%E9%87%8F%E8%A1%A8%E5%85%A5%E5%8F%A3%22%5D%0A%20%20ENTRY%20--%3E%20ACK%5B%22%E6%B8%85%E8%AF%B7%E6%B1%82%E6%BA%90%EF%BC%8C%E8%AF%BB%E6%95%B0%E6%8D%AE%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20ACK%20--%3E%20FLAG%5B%22%E7%BD%AE%20volatile%20%E6%A0%87%E5%BF%97%E6%88%96%E6%8A%95%E9%80%92%E9%98%9F%E5%88%97%22%5D%0A%20%20FLAG%20--%3E%20RET%5B%22mret%20%E8%BF%94%E5%9B%9E%E8%A2%AB%E6%89%93%E6%96%AD%E7%9A%84%E4%BB%A3%E7%A0%81%22%5D%0A%20%20FLAG%20--%3E%20DEFER%5B%22%E4%B8%BB%E5%BE%AA%E7%8E%AF%E6%88%96%E4%BB%BB%E5%8A%A1%E5%81%9A%E7%9C%9F%E6%AD%A3%E7%9A%84%E5%A4%84%E7%90%86%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,[e("span",{class:"marginnote"},"Cortex-M3 的中断入口是 12 个周期（零等待内存下），咬尾中断把连续两个中断之间的出栈再入栈压到 6 周期；NVIC 提供 4 比特优先级即 16 级。这些常数决定了「服务函数预算」的单位是百纳秒，不是毫秒。")],-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,[a("中断系统的本质是一台"),e("strong",null,"优先级仲裁机"),a("：多个请求同时挂起时，谁先被服务由优先级决定；正在服务低优先级时来了高优先级，允许抢占，反之等待。这条规则的可观测后果是"),e("strong",null,"反转的延迟账"),a("：最高优先级事件的响应延迟，等于最长的关中断窗口加最长的高于它的服务时间，而不是平均服务时间。所以「服务函数要短」不是风格建议，是给最坏情况账本减数的唯一手段。优先级分组、抢占使能这些配置项，都是在回答同一道题：你愿意让哪个事件为哪个事件让路。")],-1)),(t(),i(l,null,{default:A(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E6%9C%80%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E4%BA%8B%E4%BB%B6%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20Q1%7B%22%E6%AD%A4%E5%88%BB%E6%AD%A3%E5%A4%84%E4%BA%8E%E5%85%B3%E4%B8%AD%E6%96%AD%E7%AA%97%E5%8F%A3%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20W1%5B%22%E7%AD%89%E7%AA%97%E5%8F%A3%E5%85%B3%E9%97%AD%E6%89%8D%E8%83%BD%E5%93%8D%E5%BA%94%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E6%9C%89%E6%9B%B4%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E6%AD%A3%E5%9C%A8%E6%9C%8D%E5%8A%A1%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20W2%5B%22%E7%AD%89%E5%AE%83%E5%81%9A%E5%AE%8C%EF%BC%8C%E5%90%AB%E5%92%AC%E5%B0%BE%E8%A1%94%E6%8E%A5%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20RUN%5B%22%E7%AB%8B%E5%8D%B3%E8%BF%9B%E5%85%A5%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20W1%20--%3E%20SUM%5B%22%E6%9C%80%E5%9D%8F%E5%BB%B6%E8%BF%9F%3D%E5%90%84%E7%AD%89%E5%BE%85%E6%AE%B5%E9%80%90%E4%B8%80%E7%B4%AF%E5%8A%A0%22%5D%0A%20%20W2%20--%3E%20SUM%0A%20%20RUN%20--%3E%20OKR%5B%22%E5%BB%B6%E8%BF%9F%E5%8F%AA%E5%89%A9%E5%85%A5%E5%8F%A3%E7%9A%84%E5%9B%BA%E5%AE%9A%E5%91%A8%E6%9C%9F%22%5D%0A%20%20SUM%20--%3E%20RULE%5B%22%E6%8E%A8%E8%AE%BA%EF%BC%9A%E7%AA%97%E5%8F%A3%E4%B8%8E%E6%9C%8D%E5%8A%A1%E5%87%BD%E6%95%B0%E5%BF%85%E9%A1%BB%E7%9F%AD%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">可以把它想象成急诊分诊：重伤员可以打断轻伤员的处置，这是抢占；但若医生处置时把诊室门锁上（关中断），再重的伤员也只能在门外等。最坏延迟不取决于医生平均多快，而取决于最长的一次「锁门」加最长的一台手术。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课停在单核 MCU：多核的中断路由、核间中断与亲和性是 <a href="/cs/apic-interrupt-routing">APIC 与中断路由</a>的世界，DMA 与中断的配合留给下一课的外设协议。锁与关中断的完整搭配在<a href="/cs/lock-irq">锁与关中断</a>展开，本课只立「临界区窗口要短」的纪律。也不写 RTOS：中断里能不能调用 <code>xQueueSendFromISR</code> 这类专有接口、中断优先级与任务优先级如何对表，留给后课实时操作系统。最后一条：中断延迟不能靠示波器抓一次就下结论，最坏情况要按关中断窗口与优先级配置推算，这是后课功耗与看门狗设计的前置。</p><p><span class="marginnote">初学者容易以为示波器抓到一次 3 µs 的响应就能写进产品规格；那只是抽样，不是保证。最坏延迟是「最长关中断窗口 + 最长高优服务时间」推算出来的账，抓一万次波形也未必撞上最坏组合——预算要算出来，不要赌出来。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中断把「何时有事」交给硬件仲裁，但服务函数的长度仍是你对最坏延迟的承诺。</li><li>四条纪律：先清源、共享量 volatile、不阻塞不打印、能推迟都推迟。</li><li>配置按链路逐级核对：外设、控制器、向量表，名字错一字就是静默死循环。</li><li>最坏响应延迟由最长关中断窗口与更高优先级服务时间决定，不由平均值决定。</li><li>出处：Yiu, <em>The Definitive Guide to ARM Cortex-M3</em>；RISC-V Privileged Spec；据本栏 exception-interrupt-entry 与 interrupt-bottom-half 两课的入口与下半部口径整理。</li></ul>',6))])}const b=n(p,[["render",c]]);export{f as __pageData,b as default};
